use Agah\Erp\Modules\Treasury\TreasuryService;
if(!defined('ABSPATH')) exit;
$kind=Request::str('get','kind',10,'receipt');$accounts=[0=>'انتخاب حساب'];foreach(Db::rows('SELECT id,name FROM '.Db::t('treasury_accounts').' WHERE company_id=%d AND is_active=1 ORDER BY code',$cid) as $a)$accounts[$a['id']]=$a['name'];$parties=[0=>'انتخاب شخص'];foreach(Db::rows('SELECT id,name FROM '.Db::t('parties').' WHERE company_id=%d AND is_active=1 AND (is_customer=1 OR is_supplier=1) ORDER BY name',$cid) as $a)$parties[$a['id']]=$a['name'];
?>
<section class="erp-card"><h2><?php echo esc_html('ثبت '.TreasuryService::KINDS[$kind]); ?></h2><p>واحد مبالغ: <?php echo Ctx::unit()==='rial'?'ریال':'تومان'; ?>. برگه، سند، شماره و تسویه با هم ثبت می‌شوند؛ برگهٔ صادرشده فقط از مسیر ابطال قابل برگشت است.</p><form method="post" class="erp-form erp-treasury-form"><?php self::form('module_treasury_issue',$cid,'treasury_new'); ?><input type="hidden" name="kind" value="<?php echo esc_attr($kind); ?>"><?php self::input('doc_date','تاریخ شمسی',Jalali::format(\Agah\Erp\Core\FiscalContext::today($cid),false),'text','required data-jalali dir="ltr"');self::input('description','شرح','','text','maxlength="500"');
if($kind==='transfer'){self::select('source_account_id','حساب مبدأ',$accounts);self::select('target_account_id','حساب مقصد',$accounts);self::input('amount','مبلغ انتقال','','text','required inputmode="decimal"');}
else{
    self::select('party_id','شخص',$parties); ?><label><input type="checkbox" name="advance" value="1" <?php checked(self::value('advance',0),1); ?>><?php echo $kind==='receipt'?'پیش‌دریافت مشتری':'پیش‌پرداخت تأمین‌کننده'; ?> (بدون تخصیص به فاکتور)</label>
<h3>اقلام برگه</h3><?php self::error('items'); ?><div class="erp-scroll"><table class="erp-table"><thead><tr><th>روش و حساب</th><th>مبلغ</th><th>ارجاع</th><th>اطلاعات چک</th><th></th></tr></thead><tbody data-business-rows="items">
<?php $defaultRow=Request::str('get','method',10)==='cheque'?['method'=>'cheque','due_date'=>Jalali::format(\Agah\Erp\Core\FiscalContext::today($cid),false)]:[];$items=self::value('items',[$defaultRow]);foreach(array_values($items) as $i=>$row):require AGAH_ERP_DIR.'/views/business-treasury-row.php';endforeach; ?></tbody></table></div><button type="button" class="btn btn-outline" data-business-add="items">افزودن قلم</button>
<h3>تسویهٔ فاکتورهای صادرشده (اختیاری)</h3><?php self::error('settlements'); ?><p>فهرست شامل فاکتورهای صادرشده و برگشت قابل استرداد است. تخصیص به فاکتور شخص دیگر یا بیش از مانده، سمت سرور رد می‌شود.</p>
<?php $invoices=[0=>'بدون تخصیص'];foreach(Db::rows('SELECT i.id,i.number,i.amount,p.name FROM '.Db::t('invoices').' i JOIN '.Db::t('parties')." p ON p.company_id=i.company_id AND p.id=i.party_id WHERE i.company_id=%d AND i.status='issued' AND i.kind IN (%s,%s) ORDER BY i.id DESC",$cid,$kind==='receipt'?'sale':'purchase',$kind==='receipt'?'purchase_return':'sale_return') as $inv)$invoices[$inv['id']]=$inv['name'].' #'.$inv['number'].' / '.Money::fmt((int)$inv['amount'],Ctx::unit()); ?>
<div data-business-rows="allocations"><?php $alloc=self::value('allocations',[[]]);foreach(array_values($alloc) as $j=>$allocation): ?><div class="erp-inline-form"><label>فاکتور<select name="allocations[<?php echo (int)$j; ?>][invoice_id]"><?php foreach($invoices as $key=>$label): ?><option value="<?php echo (int)$key; ?>" <?php selected((string)($allocation['invoice_id']??0),(string)$key); ?>><?php echo esc_html($label); ?></option><?php endforeach; ?></select></label><label>مبلغ تخصیص<input name="allocations[<?php echo (int)$j; ?>][amount]" value="<?php echo esc_attr($allocation['amount']??''); ?>" inputmode="decimal"></label><button type="button" class="btn btn-outline" data-business-remove>حذف تخصیص</button></div><?php endforeach; ?></div><button type="button" class="btn btn-outline" data-business-add="allocations">افزودن تخصیص</button>
<?php } ?><button type="submit" class="btn btn-primary">صدور برگه و سند حسابداری</button></form>
<?php if($kind!=='transfer'): ?><template data-business-template="items"><?php $i='__INDEX__';$row=[];require AGAH_ERP_DIR.'/views/business-treasury-row.php'; ?></template><template data-business-template="allocations"><div class="erp-inline-form"><label>فاکتور<select name="allocations[__INDEX__][invoice_id]"><?php foreach($invoices as $key=>$label): ?><option value="<?php echo (int)$key; ?>"><?php echo esc_html($label); ?></option><?php endforeach; ?></select></label><label>مبلغ تخصیص<input name="allocations[__INDEX__][amount]" inputmode="decimal"></label><button type="button" class="btn btn-outline" data-business-remove>حذف تخصیص</button></div></template><?php endif; ?></section>
